import pickletools, glob

def get_str_after_key(ops, key):
    for i, (op, arg, pos) in enumerate(ops):
        if op.name in ('SHORT_BINUNICODE','BINUNICODE','UNICODE') and arg == key:
            j = i+1
            while j < len(ops) and ops[j][0].name == 'MEMOIZE':
                j += 1
            return ops[j][1]
    return None

rows = []
for fn in sorted(glob.glob('model_*.pkl')):
    with open(fn,'rb') as f:
        ops = list(pickletools.genops(f.read()))
    sid = get_str_after_key(ops, 'id')
    acc = get_str_after_key(ops, 'val_accuracy')
    rows.append((sid, acc))

for sid, acc in sorted(rows, key=lambda r: -r[1]):
    print(f"{sid}: {acc}")
